--- DateTime: 2020/12/15 10:51
--- Content: 光标数据模型，与服务器共用
---         1，光标由字符编号标记，拖动光标可以选中一个区间；
---         2，光标所在位置由endedIndex标记；
---         3，endedInFront标记光标停留在endedIndex所指定字符的前面还是后面，beganInFront同理；
---
local JQRichTextUtils = require("src/ui/components/reach/richtext/JQRichTextUtils")
local JQRichTextConstants = require("src/ui/components/reach/richtext/JQRichTextConstants")
local JQRichTextFormatModel = require("src/ui/components/reach/richtext/data/JQRichTextFormatModel")
local JQRichTextCursorModel = class("JQRichTextCursorModel")

function JQRichTextCursorModel:ctor(data)
    self:initData(data)
end

function JQRichTextCursorModel:initData(data)
    data = data or {}
    self.format = data.defaultFormat or JQRichTextFormatModel.new()
    self.beganIndex = data.beganIndex or -1
    self.endedIndex = data.endedIndex or -1
    self.beganInFront = data.beganInFront or false
    self.endedInFront = data.endedInFront or false
end

function JQRichTextCursorModel:setIndices(index, inFront)
    self.beganIndex = index
    self.endedIndex = index
    self.beganInFront = inFront or false
    self.endedInFront = inFront or false
end

function JQRichTextCursorModel:updateIndices(beganIndex, endedIndex, beganInFront, endedInFront)
    self.beganIndex = beganIndex
    self.endedIndex = endedIndex
    self.beganInFront = beganInFront or false
    self.endedInFront = endedInFront or false
end

function JQRichTextCursorModel:updateBeganIndex(beganIndex, beganInFront)
    self.beganIndex = beganIndex
    self.beganInFront = beganInFront or false
end

function JQRichTextCursorModel:updateEndedIndex(endedIndex, endedInFront)
    self.endedIndex = endedIndex
    self.endedInFront = endedInFront or false
end

function JQRichTextCursorModel:getIndices()
    return self.beganIndex, self.beganInFront, self.endedIndex, self.endedInFront
end

function JQRichTextCursorModel:getBeganIndex()
    return self.beganIndex, self.beganInFront
end

function JQRichTextCursorModel:getBeganCharIndex()
    local charIndex = self.beganInFront and self.beganIndex or self.beganIndex + 1
    return charIndex
end

function JQRichTextCursorModel:getEndedIndex()
    return self.endedIndex, self.endedInFront
end

function JQRichTextCursorModel:getEndedCharIndex()
    local charIndex = self.endedInFront and self.endedIndex or self.endedIndex + 1
    return charIndex
end

function JQRichTextCursorModel:getIndexOfBackSpace()
    local beganCharIndex = self.beganInFront and self.beganIndex - 1 or self.beganIndex
    local endedCharIndex = self.endedInFront and self.endedIndex - 1 or self.endedIndex
    return beganCharIndex, endedCharIndex
end

function JQRichTextCursorModel:getIndexOfDelete()
    local beganCharIndex = self.beganInFront and self.beganIndex or self.beganIndex - 1
    local endedCharIndex = self.endedInFront and self.endedIndex or self.endedIndex - 1
    return beganCharIndex, endedCharIndex
end

function JQRichTextCursorModel:isSelected()
    if self.beganIndex == -1 then
        return false
    elseif self.beganIndex ~= self.endedIndex then
        return true
    else
        return self.beganInFront ~= self.endedInFront
    end
end

function JQRichTextCursorModel:setFormat(format)
    self.format = format:clone()
    self.format:setEmpty()
end

function JQRichTextCursorModel:mergeFormat(format)
    self.format:merge(format)
    self.format:setEmpty()
end

--- only for server
function JQRichTextCursorModel:getFormatInServer()
    local format = {
        fontName    = self.format.fontName,
        fontSize    = self.format.fontSize,
        bold        = self.format.bold,
        underlineWidth = self.format.underlineWidth,
        color       = JQRichTextUtils:toHexColor(self.format.color),
        bgColor     = self.hasBgColor and JQRichTextUtils:toHexColor(self.format.bgColor),
        groupIndex  = self.format.groupIndex,
        groupAlign  = self.format.groupAlign,
    }
    return format
end

function JQRichTextCursorModel:updateFormatByName(name, value)
    if name == JQRichTextConstants.HTML.FORMAT_COLOR then
        self.format:setColor(value)
    elseif name == JQRichTextConstants.HTML.FORMAT_FONT_SIZE then
        self.format:setFontSize(value)
    elseif name == JQRichTextConstants.HTML.FORMAT_BOLD then
        self.format:setBold(value)
    elseif name == JQRichTextConstants.HTML.FORMAT_UNDERLINE then
        self.format:setUnderlineWidth(value)
    elseif name == JQRichTextConstants.HTML.FORMAT_GROUP_INDEX then
        self.format:setGroupIndex(value)
    elseif name == JQRichTextConstants.HTML.FORMAT_GROUP_ALIGN then
        self.format:setGroupAlign(value)
    elseif name == JQRichTextConstants.HTML.FORMAT_BG_COLOR then
        self.format:setBgColor(value)
    end
end

function JQRichTextCursorModel:clone()
    return {
        formatProperties = self.format:copyProperties(),
        beganIndex = self.beganIndex,
        beganInFront = self.beganInFront,
        endedIndex = self.endedIndex,
        endedInFront = self.endedInFront,
    }
end

return JQRichTextCursorModel